/** Bind hosted competitors to retained contract-bearing spans; URLs are not quotations. */
function competitorSelectors(catalog:Array<{id:string;spans:Span[]}>) {
  const hasContract=(text:string)=>[...text.matchAll(/(?<![A-Za-z0-9])(?:0x[0-9a-fA-F]{40}|[1-9A-HJ-NP-Za-km-z]{32,44})(?![A-Za-z0-9])/g)].some(match=>{
    if(match[0].startsWith('0x'))return true;
    try{return new PublicKey(match[0]).toBase58()===match[0];}catch{return false;}
  });
  const options=catalog.flatMap(source=>source.spans.filter(span=>hasContract(span.text)).map(span=>({sourceId:source.id,spanId:span.id})));
  const shape=attentionProposalSchema.shape.competitors.element.omit({quote:true,sourceId:true});
  // One branch per source, not per contract or span: full-text batches stay bounded.
  const selectors=catalog.flatMap(source=>{
    const spanIds=options.filter(option=>option.sourceId===source.id).map(option=>option.spanId);
    return spanIds.length?[shape.extend({sourceId:z.literal(source.id),spanId:z.enum(spanIds as [string,...string[]])}).strict()]:[];
  });
  const selection=selectors.length===1?selectors[0]!:selectors.length>1?z.union(selectors as [typeof selectors[number],typeof selectors[number],...typeof selectors[number][]]):shape.extend({sourceId:z.string().min(1),spanId:z.string().min(1)}).strict();
  return {options,competitors:z.array(selection).max(options.length?10:0)};
}
