export function comparisonAccountingWireFor(leads:ComparisonLead[],marked=false){
  const markedRepresentation=z.union([
    representationWire.extend({status:z.literal('BOUND'),token:attentionProposalSchema.shape.competitors.element.shape.token,unresolvedKind:z.literal('NONE')}),
    representationWire.extend({status:z.enum(['UNRELATED','INADEQUATE']),token:z.null(),unresolvedKind:z.literal('NONE')}),
    representationWire.extend({status:z.literal('UNRESOLVED'),token:z.null(),unresolvedKind:z.enum(['PUBLIC_SUPPORT_GAP','MEANINGFUL_ASSOCIATION_CONFLICT','MISSING_NECESSARY_CONTEXT'])}),
  ]);
  const entry=marked?comparisonAccountingArraySchema.shape.decisions.element.extend({representation:markedRepresentation}):comparisonAccountingArraySchema.shape.decisions.element;
  return comparisonAccountingArraySchema.extend({decisions:z.array(leads.some(l=>l.sourceIds.length)?entry:entry.extend({subjectComparison:comparisonSubjectWireSchema.extend({status:z.literal('UNRESOLVED'),currentSubject:z.null(),fetchedRefs:z.array(leadRef).max(0)})})).max(32)}).strict();
}
