export const comparisonLeadSupportInstruction='Reassess ONLY independently rejected representation judgments using the identical source catalog and recorded own recovery. Preserve every accepted representation and ALL accounting, subjectComparison and evidenceAdequacy fields exactly. Do not reject a comparative token solely for having a DIFFERENT mint: that is expected. An INADEQUATE entry grade needs positive poor public-verifiability or sparse market-only narrative support, not contract inequality, absent target address or an HTTP error alone. Cite the actual retained market-only record/indexed role and reviewed recovery context supporting that poor-support judgment. BOUND requires specific project/narrative association and a literal fetched mint, never name alone. UNRESOLVED remains correct for genuine conflicting association or missing necessary project/publication evidence. The initial rejection is evidence to address, not instructions to accept a negative. No fabricated contents or facts. A fresh full independent review must accept any replacement. ' + comparisonAccountingInstruction;
export function comparisonLeadSupportRepairEligible(proposal:{decisions:Record<string,unknown>},review:{decisions:Record<string,unknown>}){
  const p=proposal.decisions as Record<string,{accounting:{role:string};representation:{status:string}}>;
  const r=review.decisions as Record<string,AccountingDecision['review']>;
  return Object.keys(p).some(id=>!r[id]?.representation.accepted)&&Object.keys(p).every(id=>r[id]?.accounting.accepted&&r[id]?.subjectComparison.accepted&&r[id]?.evidenceAdequacy.accepted&&(r[id]?.representation.accepted||p[id].accounting.role==='MARKET_OR_INDEX_RECORD'));
}
export function comparisonLeadSupportRepairValid(original:{decisions:Record<string,unknown>},initialReview:{decisions:Record<string,unknown>},replacement:{decisions:Record<string,unknown>},review:{decisions:Record<string,unknown>}){
  const before=initialReview.decisions as Record<string,AccountingDecision['review']>,after=review.decisions as Record<string,AccountingDecision['review']>;
  return Object.keys(original.decisions).every(id=>{
    const a=original.decisions[id] as Record<string,unknown>,b=replacement.decisions[id] as Record<string,unknown>;
    return !!b&&['accounting','subjectComparison','evidenceAdequacy',...(before[id].representation.accepted?['representation']:[])].every(k=>JSON.stringify(a[k])===JSON.stringify(b[k]))&&Object.values(after[id]??{}).length===4&&Object.values(after[id]).every(r=>r.accepted);
  });
}
