  if(!scope.complete||!sources.length||sources.some(s=>!s||s.text.length>6000))throw Error('ATT_NARRATIVE_SUPPORT_SCOPE_INCOMPLETE');
  const catalog=sources.map(({text,...s})=>({...s,spans:sourceSpans(s.id,text)}));
  const selection=z.object({sourceId:z.string(),spanId:z.string()}).strict();
  const support=z.object({status:z.enum(['SUBSTANTIVE_SUPPORT','PUBLIC_SUPPORT_GAP','CONTEXT_ONLY','UNRESOLVED']),criteria:z.array(narrativeCriterionSchema).max(2),rationale:z.string().min(8).max(1000),citations:z.array(selection).max(3)}).strict();
