  const independentPrompt=JSON.stringify({instruction:'Independently try to disprove every proposed support decision and criterion against EVERY unchanged original source span. accepted means the judgment is justified, not that a source supports a positive story. Mark inspectionComplete only after reading all spans. Reject unsupported negative inversions, name-based stories and missing-context grades. '+narrativeSupportRule,...context,proposal:selected});
