    const finalScope={...qualified,rawArtifacts:independentEntry?{...qualified.rawArtifacts,...base.rawArtifacts}:qualified.rawArtifacts,comparisonCoverage:compared.coverage,comparisonPublicSupport:compared.publicSupport,comparisonComplete:qualified.comparisonComplete===true&&compared.review.candidateSet?.complete===true};
