async function qualifyCompleteComparison(read:AttentionRead,token:TokenRef,proposal:z.output<typeof attentionProposalSchema>,review:z.output<typeof attentionReviewSchema>,key:string,fetcher:typeof fetch,wait:(ms:number)=>Promise<void>,rawArtifacts:Record<string,string>,signal?:AbortSignal,routing?:SourceModelRouting){
  const program=comparisonProgram({...read,rawArtifacts:{...read.rawArtifacts,...rawArtifacts}},token,proposal,review,rawArtifacts);
  let step=program.next();
  while(!step.done){
    const {id,prompt,schema}=step.value;
    const result=await request(prompt,schema,key,fetcher,(raw,retrying,transportAttempt,responseAttempt)=>{if(transportAttempt)rawArtifacts[`${id}-transport-attempt-${transportAttempt}`]=raw;else{rawArtifacts[`${id}-response`]=raw;if(retrying)rawArtifacts[`${id}-response-attempt-${responseAttempt??1}`]=raw;}},wait,signal,'ATT_MODEL',routing);
    step=program.next(result.value);
  }
  return step.value;
}
